  page.on('dialog', (d) => d.accept('e2e preset'));

  const confirm = async (label) => {
    const btn = page.getByRole('button', { name: label });
    await btn.waitFor();
    await page.waitForFunction((l) => [...document.querySelectorAll('button')].some((b) => b.textContent.trim() === l && !b.disabled), label);
    await btn.click();
    await page.waitForSelector('#rows:not([data-review])');
  };

  await page.goto(BASE + '/ui2/organizer');
  // Add exchange 0 by id.
  await page.getByText('Save an exchange by id').click();
  await page.fill('input[name=exchange]', '0');
  await page.getByRole('button', { name: 'Review save exchange' }).click();
  await confirm('Confirm save exchange');
  await page.waitForSelector('#organizer-note');
  const note1 = await page.textContent('#organizer-note');
  if (!/saved to the Inbox as item #(\d+)/.test(note1)) throw new Error('add note: ' + note1);
  if (!(await page.isVisible('#org-detail'))) throw new Error('detail not open after add');

  // Set title.
  await page.fill('#org-detail input[name=title]', 'E2E title');
  await page.getByRole('button', { name: 'Review title, highlight and note' }).click();
  await confirm('Confirm annotations');
  if (!(await page.textContent('table.organizer-items')).includes('E2E title')) throw new Error('title not shown');

  // Set workflow status.
  await page.check('#org-detail input[name=status][value=done]');
  await page.getByRole('button', { name: 'Review workflow status' }).click();
  await confirm('Confirm workflow status');
  if (!(await page.textContent('table.organizer-items')).includes('done')) throw new Error('status not shown');

  // Create a collection.
  await page.getByText('Create collection').click();
  await page.fill('details:has(summary:text("Create collection")) input[name=name]', 'e2e-coll');
  await page.getByRole('button', { name: 'Review new collection' }).click();
  await confirm('Confirm collection change');

  // Open the item and move it to the new collection.
  await page.locator('table.organizer-items a', { hasText: '#' }).first().click();
  await page.waitForSelector('#org-detail');
  await page.locator('#org-detail label', { hasText: 'e2e-coll' }).locator('input').check();
  await page.getByRole('button', { name: 'Review move to destination' }).click();
  await confirm('Confirm item move');
  const row = await page.textContent('table.organizer-items tbody');
  if (!row.includes('e2e-coll')) throw new Error('move not shown: ' + row);

  // Filters and preset save.
  await page.selectOption('select[name=workflow]', 'done');
  await page.waitForFunction(() => location.search.includes('workflow=done'));
  await page.click('#org-preset-save');
  await page.waitForFunction(() => document.getElementById('org-preset-status').textContent.includes('Saved'));
  await page.screenshot({ path: OUT + '/organizer-1280.png', fullPage: true });

  // Delete the collection keeping its items.
  await page.goto(BASE + '/ui2/organizer');
  await page.locator('section:has(h4:text("e2e-coll")) summary', { hasText: 'Delete' }).click();
  await page.getByRole('button', { name: 'Review delete, keep items (move to Inbox)' }).click();
  await confirm('Confirm collection delete');
  const note2 = await page.textContent('#organizer-note');
  if (!/moved to the Inbox/.test(note2)) throw new Error('delete note: ' + note2);
  const body = await page.textContent('table.organizer-items tbody');
  if (body.includes('e2e-coll') || !body.includes('Inbox')) throw new Error('item not back in Inbox: ' + body);

  // CSV export link.
  const csv = await page.evaluate(async () => (await fetch(document.querySelector('a[download]').href)).text());
  if (!csv.startsWith('"ID","Title"') || !csv.includes('E2E title')) throw new Error('csv: ' + csv);

  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto(BASE + '/ui2/organizer?item=1');
  await page.screenshot({ path: OUT + '/organizer-390.png', fullPage: true });
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);

  await browser.close();
  if (errors.length) { console.log('ERRORS\n' + errors.join('\n')); process.exit(1); }
  console.log('E2E OK; phone horizontal overflow px =', overflow);
})().catch((e) => { console.error(e); process.exit(1); });
